CREATE TABLE IF NOT EXISTS ownership_charter_principles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, principle_code text NOT NULL, title text NOT NULL, principle_text text NOT NULL, scope text, legal_status text NOT NULL DEFAULT 'Proposed', review_required boolean NOT NULL DEFAULT true, status text NOT NULL DEFAULT 'Active', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS protected_interests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, interest_type text NOT NULL, interest_holder text, jurisdiction text NOT NULL DEFAULT 'Nigeria', originating_community text, asset_or_right_reference text, protection_basis text, status text NOT NULL DEFAULT 'Proposed', evidence_reference text, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reserved_consent_matters (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, matter_code text NOT NULL, matter_title text NOT NULL, trigger_description text NOT NULL, consent_route text NOT NULL, minimum_approval text, affected_interests text, legal_review_required boolean NOT NULL DEFAULT true, status text NOT NULL DEFAULT 'Proposed', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS community_benefit_arrangements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, jurisdiction text NOT NULL DEFAULT 'Nigeria', community_name text, arrangement_type text NOT NULL, benefit_description text, eligibility_basis text, benefit_metric text, governance_body text, review_frequency text, legal_instrument_reference text, status text NOT NULL DEFAULT 'Proposed', notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cultural_heritage_protections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, jurisdiction text NOT NULL DEFAULT 'Nigeria', community_name text, heritage_type text NOT NULL, protection_requirement text NOT NULL, prohibited_use text, consent_requirement text, custodian_role text, evidence_reference text, status text NOT NULL DEFAULT 'Proposed', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ownership_succession_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, rule_title text NOT NULL, trigger_event text NOT NULL, succession_route text NOT NULL, continuity_principle text, dispute_route text, legal_review_required boolean NOT NULL DEFAULT true, status text NOT NULL DEFAULT 'Proposed', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS continental_entity_protections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_name text NOT NULL, country_code text NOT NULL, local_entity_name text, founding_interest_reference text, local_participation_principle text, benefit_sharing_principle text, reserved_matter_reference text, local_law_review_status text NOT NULL DEFAULT 'Required', status text NOT NULL DEFAULT 'Planned', notes text, created_at timestamptz NOT NULL DEFAULT now());
