INSERT INTO ownership_charter_principles(entity_name,principle_code,title,principle_text,scope) SELECT 'OSANVAULT AFRICA LTD','OFC-01','Founding Continuity','Institutional growth should not be used as a mechanism to arbitrarily erase or dilute legitimately documented founding interests.','Group and controlled entities' WHERE NOT EXISTS (SELECT 1 FROM ownership_charter_principles WHERE principle_code='OFC-01');
INSERT INTO ownership_charter_principles(entity_name,principle_code,title,principle_text,scope) SELECT 'OSANVAULT AFRICA LTD','OFC-02','Indigenous Rights Respect','Where a project touches indigenous, customary, community or ancestral interests, applicable rights and consent requirements must be identified and respected before material action.','Jurisdiction and project specific' WHERE NOT EXISTS (SELECT 1 FROM ownership_charter_principles WHERE principle_code='OFC-02');
INSERT INTO ownership_charter_principles(entity_name,principle_code,title,principle_text,scope) SELECT 'OSANVAULT AFRICA LTD','OFC-03','Benefit Participation','Where legally and commercially appropriate, communities connected to originating assets or projects should have a transparent route to defined benefits or participation.','Asset/project specific' WHERE NOT EXISTS (SELECT 1 FROM ownership_charter_principles WHERE principle_code='OFC-03');
INSERT INTO ownership_charter_principles(entity_name,principle_code,title,principle_text,scope) SELECT 'OSANVAULT AFRICA LTD','OFC-04','Cultural Stewardship','Cultural knowledge, sacred places, heritage assets and community identity must not be treated as ordinary commercial assets without appropriate consent and legal review.','Jurisdiction and asset specific' WHERE NOT EXISTS (SELECT 1 FROM ownership_charter_principles WHERE principle_code='OFC-04');
INSERT INTO ownership_charter_principles(entity_name,principle_code,title,principle_text,scope) SELECT 'OSANVAULT AFRICA LTD','OFC-05','Local Law Supremacy','This charter is a governance framework and cannot override constitutions, statutes, customary law where legally recognized, land titles, regulatory requirements or court orders.','All jurisdictions' WHERE NOT EXISTS (SELECT 1 FROM ownership_charter_principles WHERE principle_code='OFC-05');
INSERT INTO reserved_consent_matters(entity_name,matter_code,matter_title,trigger_description,consent_route,minimum_approval,affected_interests) SELECT 'OSANVAULT AFRICA LTD','RCM-01','Protected-Interest Dilution','Any transaction that could materially dilute a documented protected founding or community interest.','Constitution + shareholder/rights instrument + legal review','As defined by adopted instrument','Founding/community interests' WHERE NOT EXISTS (SELECT 1 FROM reserved_consent_matters WHERE matter_code='RCM-01');
INSERT INTO reserved_consent_matters(entity_name,matter_code,matter_title,trigger_description,consent_route,minimum_approval,affected_interests) SELECT 'OSANVAULT AFRICA LTD','RCM-02','Protected Asset Transfer','Transfer, encumbrance or restructuring of an asset subject to documented community, indigenous or founding protections.','Asset instrument + governing body + legal review','As defined by applicable instrument','Protected asset interests' WHERE NOT EXISTS (SELECT 1 FROM reserved_consent_matters WHERE matter_code='RCM-02');
INSERT INTO reserved_consent_matters(entity_name,matter_code,matter_title,trigger_description,consent_route,minimum_approval,affected_interests) SELECT 'OSANVAULT AFRICA LTD','RCM-03','Heritage Impact','Commercial activity reasonably likely to materially affect documented cultural heritage interests.','Community/custodian consultation + legal review','Legally required consent/approval','Cultural heritage' WHERE NOT EXISTS (SELECT 1 FROM reserved_consent_matters WHERE matter_code='RCM-03');
INSERT INTO reserved_consent_matters(entity_name,matter_code,matter_title,trigger_description,consent_route,minimum_approval,affected_interests) SELECT 'OSANVAULT AFRICA LTD','RCM-04','Control or Constitutional Change','Material change to control, constitutional rights or protected governance arrangements.','Board/shareholder route + legal review','As required by adopted constitution/instruments','Founding and shareholder interests' WHERE NOT EXISTS (SELECT 1 FROM reserved_consent_matters WHERE matter_code='RCM-04');